ATTACH DATABASE '' AS aux; PRAGMA aux.page_size=1024; PRAGMA aux.cache_size=50; BEGIN; CREATE TABLE aux.t1(a INTEGER PRIMARY KEY, b); INSERT INTO aux.t1 VALUES(1, substr(replace(hex(zeroblob(450)), '00', '1.'), 1, 900)); INSERT INTO aux.t1 VALUES(2, substr(replace(hex(zeroblob(450)), '00', '1.'), 1, 900)); INSERT INTO aux.t1 VALUES(3, substr(replace(hex(zeroblob(450)), '00', '1.'), 1, 900)); CREATE TABLE aux.t2(a INTEGER PRIMARY KEY, b); WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<100) INSERT INTO aux.t2 SELECT x, substr(replace(hex(zeroblob(450)), '00', CAST(x AS TEXT) || '.'), 1, 900) FROM c; COMMIT; UPDATE aux.t1 SET b=substr(replace(hex(zeroblob(450)), '00', '2.'), 1, 900); INSERT INTO main.result(seq,ok) SELECT a, b=substr(replace(hex(zeroblob(450)), '00', '2.'), 1, 900) FROM aux.t1 ORDER BY a; DETACH DATABASE aux;